import { formatMoney, formatPercent } from './comparison.js';

const escape = value => String(value ?? '').replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
const number = value => new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 1 }).format(value);
const amount = value => `<span title="${escape(formatMoney(value, false))}">${escape(formatMoney(value))}</span>`;
const rate = value => formatPercent(typeof value === 'number' ? value * 100 : null);

export function renderComparison(root, comparison) {
  root.classList.add('ve-comparison');
  root.setAttribute('aria-labelledby', 've-comparison-title');
  const { rows, winner, methodology: method } = comparison;
  const maxResidual = Math.max(1, ...rows.filter(row => row.valid).map(row => Math.abs(row.residual)));
  root.innerHTML = `
    <header class="ve-comparison-heading"><div><span class="ve-eyebrow">UM LOTE. DIFERENTES ESTRATÉGIAS.</span><h2 id="ve-comparison-title" tabindex="-1">Mais área nem sempre<br>significa mais oportunidade.</h2><p>Compare as alternativas com as mesmas premissas de terreno e margem. Todos os valores abaixo são fictícios.</p></div><span class="ve-comparison-badge">Simulação ilustrativa</span></header>
    <div class="ve-comparison-overview">
      <div class="ve-residual-chart" aria-label="Comparação do valor residual estimado do terreno"><h3>Valor residual do terreno <small>Preservando ${rate(method.targetMargin)} de margem sobre vendas</small></h3>${rows.map(row => `<button type="button" class="ve-residual-row" data-compare-scenario="${escape(row.id)}" data-comparison-highlight="${escape(row.id)}" aria-label="Explorar ${escape(row.name)}: valor residual ${escape(formatMoney(row.residual, false))}"><span>${escape(row.shortName)}</span><span class="ve-residual-track"><i style="width:${row.valid ? Math.max(2, Math.abs(row.residual) / maxResidual * 100) : 0}%" class="${row.residual < 0 ? 'negative' : ''}"></i></span><strong>${escape(formatMoney(row.residual))}</strong></button>`).join('')}</div>
      <aside class="ve-comparison-winner">${winner ? `<span class="ve-winner-kicker">CENÁRIO COM MAIOR POTENCIAL ESTIMADO</span><h3>${escape(winner.name)}</h3><strong>${escape(formatMoney(winner.residual))}</strong><p>Maior valor residual neste exemplo, após reservar a margem alvo. O resultado depende das premissas abaixo.</p><button type="button" data-compare-scenario="${escape(winner.id)}">Explorar cenário em 3D <span aria-hidden="true">↗</span></button>` : '<h3>Premissas a confirmar</h3><p>Não há um cenário destacado sem dados completos, método definido e resultado suficiente para o valor assumido do terreno.</p>'}</aside>
    </div>
    <div class="ve-comparison-table-wrap" tabindex="0" role="region" aria-label="Tabela comparativa dos cenários; deslize para consultar todos os indicadores"><table><caption>Indicadores ilustrativos · venda das unidades · mesmo terreno</caption><thead><tr><th scope="col">Alternativa</th><th scope="col">Potencial construtivo</th><th scope="col">Unidades</th><th scope="col">VGV</th><th scope="col">Custo total</th><th scope="col">Residual do terreno</th><th scope="col">Retorno sobre custo</th><th scope="col">Resultado no exemplo</th></tr></thead><tbody>${rows.map(row => `<tr data-comparison-highlight="${escape(row.id)}"><th scope="row"><button type="button" data-compare-scenario="${escape(row.id)}">${escape(row.shortName)} <span aria-hidden="true">↗</span></button></th><td><b>${row.builtArea === null ? 'A definir' : number(row.builtArea) + ' m²'}</b><small>${row.floors ?? '—'} pav. · CA ${row.coefficient === null ? '—' : number(row.coefficient)}×</small></td><td>${row.units ?? '—'}</td><td>${amount(row.revenue)}</td><td>${amount(row.totalCost)}</td><td>${amount(row.residual)}</td><td>${formatPercent(row.profitability)}</td><td><span class="ve-financial-state" data-tone="${escape(row.viability.tone)}">${escape(row.viability.label)}</span></td></tr>`).join('')}</tbody></table></div>
    <p class="ve-comparison-note">Custo total inclui construção, custos indiretos, comercialização e o terreno assumido em ${formatMoney(method.landPrice)}. O retorno é do projeto completo, sem prazo definido; não é uma taxa anual. A viabilidade legal ainda não foi validada.</p>
    <details class="ve-methodology"><summary>Como calculamos · premissas e metodologia <span aria-hidden="true">+</span></summary><div class="ve-methodology-content"><p><strong>Critério de destaque:</strong> ${escape(method.label)}. Um empate, premissas incompletas ou residual inferior ao preço assumido do terreno impedem a recomendação.</p><div class="ve-assumptions"><span>Terreno <b>${formatMoney(method.landPrice)}</b></span><span>Indiretos sobre obra <b>${rate(method.overheadRate)}</b></span><span>Comercialização sobre VGV <b>${rate(method.sellingRate)}</b></span><span>Margem alvo sobre VGV <b>${rate(method.targetMargin)}</b></span></div><div class="ve-method-table"><table><caption>Premissas inventadas para a demonstração, sem cotação de mercado</caption><thead><tr><th scope="col">Cenário</th><th scope="col">Venda / m² vendável</th><th scope="col">Obra / m² construído</th><th scope="col">Eficiência vendável</th></tr></thead><tbody>${rows.map(row => `<tr><th scope="row">${escape(row.shortName)}</th><td>${formatMoney(row.inputs.salePricePerM2, false)}</td><td>${formatMoney(row.inputs.constructionCostPerM2, false)}</td><td>${rate(row.inputs.efficiency)}</td></tr>`).join('')}</tbody></table></div><ol><li>Área vendável = área construída × eficiência. VGV = área vendável × preço de venda.</li><li>Custo sem terreno = obra + custos indiretos + comercialização.</li><li>Residual = VGV − custo sem terreno − margem alvo × VGV.</li><li>Retorno sobre custo = (VGV − custo total) ÷ custo total × 100.</li></ol><p>Hipótese comum: venda integral das unidades, inclusive flats. Não estima renda de locação. Cronograma, financiamento, tributação detalhada, outorga e particularidades de cada terreno exigem uma análise própria.</p></div></details>
  `;
}
